import app from 'flarum/common/app';
const idSlug = thing => thing.id + (thing.slug ? '-' + thing.slug : '');

/** "/courses/12-baking-bread" */
export const courseUrl = course => app.route('syllabus.course', {
  id: idSlug(course)
});
export const lessonUrl = (course, lesson) => app.route('syllabus.lesson', {
  id: idSlug(course),
  lesson: idSlug(lesson)
});
export const certificateUrl = code => app.route('syllabus.certificate', {
  code
});

/** The numeric id at the front of an "12-some-slug" route parameter. */
export const routeId = param => parseInt(String(param || ''), 10) || 0;
flarum.reg.add('ernestdefoe-syllabus', 'common/urls', { courseUrl: courseUrl,lessonUrl: lessonUrl,certificateUrl: certificateUrl,routeId: routeId, });