import app from 'flarum/forum/app';
import Notification from 'flarum/forum/components/Notification';
import { certificateUrl, lessonUrl } from '../common/urls';
const t = (key, params = {}) => app.translator.trans(`ernestdefoe-syllabus.forum.notifications.${key}`, params);

/** The course a notification points at, or null if it has since been deleted. */
function course(notification) {
  const subject = notification.subject();
  return subject ? {
    id: Number(subject.id()),
    slug: subject.slug?.() || '',
    title: subject.title?.() || ''
  } : null;
}
function lessonHref(notification) {
  const c = course(notification);
  const content = notification.content() || {};
  return c ? lessonUrl(c, {
    id: content.lessonId,
    slug: content.lessonSlug
  }) : app.route('syllabus.index');
}
export class AssignmentReviewedNotification extends Notification {
  icon() {
    return this.attrs.notification.content()?.status === 'passed' ? 'fas fa-circle-check' : 'fas fa-rotate-left';
  }
  href() {
    return lessonHref(this.attrs.notification);
  }
  content() {
    const n = this.attrs.notification;
    return t(n.content()?.status === 'passed' ? 'reviewed_passed' : 'reviewed_needs_work', {
      user: n.fromUser(),
      lesson: n.content()?.lessonTitle || ''
    });
  }
  excerpt() {
    return course(this.attrs.notification)?.title || null;
  }
}
export class SubmissionReceivedNotification extends Notification {
  icon() {
    return 'fas fa-inbox';
  }
  href() {
    return app.route('syllabus.teach') + '?tab=review';
  }
  content() {
    const n = this.attrs.notification;
    return t('submission', {
      user: n.fromUser(),
      lesson: n.content()?.lessonTitle || ''
    });
  }
  excerpt() {
    return course(this.attrs.notification)?.title || null;
  }
}
export class NewLessonNotification extends Notification {
  icon() {
    return 'fas fa-book-open';
  }
  href() {
    return lessonHref(this.attrs.notification);
  }
  content() {
    return t('new_lesson', {
      course: course(this.attrs.notification)?.title || ''
    });
  }
  excerpt() {
    return this.attrs.notification.content()?.lessonTitle || null;
  }
}
export class CourseCompletedNotification extends Notification {
  icon() {
    return 'fas fa-award';
  }
  href() {
    const code = this.attrs.notification.content()?.code;
    return code ? certificateUrl(code) : app.route('syllabus.index');
  }
  content() {
    return t('completed', {
      course: course(this.attrs.notification)?.title || ''
    });
  }
  excerpt() {
    return null;
  }
}