import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import LinkButton from 'flarum/common/components/LinkButton';
import UserPage from 'flarum/forum/components/UserPage';
import Switch from 'flarum/common/components/Switch';
import registerWidgets from './widgets';
import { AssignmentReviewedNotification, CourseCompletedNotification, NewLessonNotification, SubmissionReceivedNotification } from './notifications';
export { default as extend } from './extend';
const t = key => app.translator.trans(`ernestdefoe-syllabus.forum.${key}`);

/*
 * Everything here runs on every page for every visitor, so it is only the
 * wiring. Every page is its own chunk, fetched the first time it is opened.
 */
app.initializers.add('ernestdefoe-syllabus', () => {
  app.routes['syllabus.index'] = {
    path: '/courses',
    component: () => import(/* webpackChunkName: 'forum/pages/CataloguePage', webpackMode: 'lazy-once' */ './pages/CataloguePage')
  };
  app.routes['syllabus.teach'] = {
    path: '/courses/teach',
    component: () => import(/* webpackChunkName: 'forum/pages/TeachPage', webpackMode: 'lazy-once' */ './pages/TeachPage')
  };
  app.routes['syllabus.new'] = {
    path: '/courses/new',
    component: () => import(/* webpackChunkName: 'forum/pages/CourseEditorPage', webpackMode: 'lazy-once' */ './pages/CourseEditorPage')
  };
  app.routes['syllabus.course'] = {
    path: '/courses/:id',
    component: () => import(/* webpackChunkName: 'forum/pages/CoursePage', webpackMode: 'lazy-once' */ './pages/CoursePage')
  };
  app.routes['syllabus.edit'] = {
    path: '/courses/:id/edit',
    component: () => import(/* webpackChunkName: 'forum/pages/CourseEditorPage', webpackMode: 'lazy-once' */ './pages/CourseEditorPage')
  };
  app.routes['syllabus.lesson.new'] = {
    path: '/courses/:id/lessons/new',
    component: () => import(/* webpackChunkName: 'forum/pages/LessonEditorPage', webpackMode: 'lazy-once' */ './pages/LessonEditorPage')
  };
  app.routes['syllabus.lesson'] = {
    path: '/courses/:id/lessons/:lesson',
    component: () => import(/* webpackChunkName: 'forum/pages/LessonPage', webpackMode: 'lazy-once' */ './pages/LessonPage')
  };
  app.routes['syllabus.lesson.edit'] = {
    path: '/courses/:id/lessons/:lesson/edit',
    component: () => import(/* webpackChunkName: 'forum/pages/LessonEditorPage', webpackMode: 'lazy-once' */ './pages/LessonEditorPage')
  };
  app.routes['syllabus.certificate'] = {
    path: '/certificates/:code',
    component: () => import(/* webpackChunkName: 'forum/pages/CertificatePage', webpackMode: 'lazy-once' */ './pages/CertificatePage')
  };
  app.routes['user.courses'] = {
    path: '/u/:username/courses',
    component: () => import(/* webpackChunkName: 'forum/pages/UserCoursesPage', webpackMode: 'lazy-once' */ './pages/UserCoursesPage')
  };
  app.notificationComponents.syllabusAssignmentReviewed = AssignmentReviewedNotification;
  app.notificationComponents.syllabusSubmissionReceived = SubmissionReceivedNotification;
  app.notificationComponents.syllabusNewLesson = NewLessonNotification;
  app.notificationComponents.syllabusCourseCompleted = CourseCompletedNotification;
  extend(IndexSidebar.prototype, 'navItems', function (items) {
    if (!app.forum.attribute('canViewCourses') || app.forum.attribute('syllabusShowNav') === false) return;
    items.add('courses', m(LinkButton, {
      href: app.route('syllabus.index'),
      icon: "fas fa-chalkboard-user"
    }, t('nav')), 4);
  });
  extend(UserPage.prototype, 'navItems', function (items) {
    if (!this.user || !app.forum.attribute('canViewCourses')) return;
    items.add('courses', m(LinkButton, {
      href: app.route('user.courses', {
        username: this.user.slug()
      }),
      icon: "fas fa-chalkboard-user"
    }, t('profile.nav')), 80);
  });
  extend('flarum/forum/components/NotificationGrid', 'notificationTypes', function (items) {
    items.add('syllabusAssignmentReviewed', {
      name: 'syllabusAssignmentReviewed',
      icon: 'fas fa-circle-check',
      label: t('settings.notify_reviewed')
    });
    items.add('syllabusCourseCompleted', {
      name: 'syllabusCourseCompleted',
      icon: 'fas fa-award',
      label: t('settings.notify_completed')
    });
    items.add('syllabusNewLesson', {
      name: 'syllabusNewLesson',
      icon: 'fas fa-book-open',
      label: t('settings.notify_new_lesson')
    });
    if (app.forum.attribute('canCreateCourses')) {
      items.add('syllabusSubmissionReceived', {
        name: 'syllabusSubmissionReceived',
        icon: 'fas fa-inbox',
        label: t('settings.notify_submission')
      });
    }
  });
  extend('flarum/forum/components/SettingsPage', 'privacyItems', function (items) {
    if (!app.forum.attribute('canViewCourses')) return;
    const user = this.user;
    items.add('syllabusShowCourses', m(Switch, {
      state: user.preferences()?.syllabusShowCourses !== false,
      loading: this.syllabusLoading,
      onchange: value => {
        this.syllabusLoading = true;
        user.savePreferences({
          syllabusShowCourses: value
        }).finally(() => {
          this.syllabusLoading = false;
          m.redraw();
        });
      }
    }, t('settings.show_courses')));
  });
  registerWidgets();
});flarum.reg.addChunkModule('ernestdefoe-syllabus:forum/pages/CataloguePage', '94', 'ernestdefoe-syllabus', 'forum/pages/CataloguePage');
flarum.reg.addChunkModule('ernestdefoe-syllabus:forum/pages/TeachPage', '850', 'ernestdefoe-syllabus', 'forum/pages/TeachPage');
flarum.reg.addChunkModule('ernestdefoe-syllabus:forum/pages/CourseEditorPage', '539', 'ernestdefoe-syllabus', 'forum/pages/CourseEditorPage');
flarum.reg.addChunkModule('ernestdefoe-syllabus:forum/pages/CoursePage', '768', 'ernestdefoe-syllabus', 'forum/pages/CoursePage');
flarum.reg.addChunkModule('ernestdefoe-syllabus:forum/pages/LessonEditorPage', '436', 'ernestdefoe-syllabus', 'forum/pages/LessonEditorPage');
flarum.reg.addChunkModule('ernestdefoe-syllabus:forum/pages/LessonPage', '185', 'ernestdefoe-syllabus', 'forum/pages/LessonPage');
flarum.reg.addChunkModule('ernestdefoe-syllabus:forum/pages/CertificatePage', '740', 'ernestdefoe-syllabus', 'forum/pages/CertificatePage');
flarum.reg.addChunkModule('ernestdefoe-syllabus:forum/pages/UserCoursesPage', '844', 'ernestdefoe-syllabus', 'forum/pages/UserCoursesPage');
flarum.reg.addChunkModule('ernestdefoe-syllabus:forum/pages/CataloguePage', '94', 'ernestdefoe-syllabus', 'common/api');
flarum.reg.addChunkModule('ernestdefoe-syllabus:forum/pages/CataloguePage', '94', 'ernestdefoe-syllabus', 'forum/components/CourseCard');
flarum.reg.addChunkModule('ernestdefoe-syllabus:forum/pages/CataloguePage', '94', 'ernestdefoe-syllabus', 'forum/components/ProgressBar');
flarum.reg.addChunkModule('ernestdefoe-syllabus:forum/pages/CataloguePage', '94', 'ernestdefoe-syllabus', 'forum/components/util');
flarum.reg.addChunkModule('ernestdefoe-syllabus:forum/pages/CourseEditorPage', '539', 'ernestdefoe-syllabus', 'forum/components/Field');
flarum.reg.addChunkModule('ernestdefoe-syllabus:forum/pages/CourseEditorPage', '539', 'ernestdefoe-syllabus', 'forum/components/SyllabusTextEditor');
flarum.reg.addChunkModule('ernestdefoe-syllabus:forum/pages/CourseEditorPage', '539', 'ernestdefoe-syllabus', 'common/sortable');
flarum.reg.addChunkModule('ernestdefoe-syllabus:forum/pages/CoursePage', '768', 'ernestdefoe-syllabus', 'forum/components/OutlineList');
flarum.reg.addChunkModule('ernestdefoe-syllabus:forum/pages/LessonPage', '185', 'ernestdefoe-syllabus', 'forum/components/Assignment');